const input = $input.item.json;

const prompts = {
  instagram_post: `Create an Instagram post for Mitch street food:
Topic: ${input.topic || 'new menu item'}
Tone: ${input.tone || 'fun, edgy, vampire-themed'}
Target: Young professionals in Bucharest

Provide:
1. Catchy caption (max 150 characters)
2. Longer description with emojis
3. 15 relevant hashtags (mix of popular and niche)
4. Best posting time recommendation
5. Story ideas to complement the post`,

  facebook_post: `Create a Facebook post for Mitch:
Topic: ${input.topic}
Tone: More detailed, community-focused
Include:
- Engaging opening question
- Story about the food/ingredient
- Call to action
- When/where to find us`,

  weekly_calendar: `Create a week of social media content for Mitch (Mon-Sun):
Theme: ${input.theme || 'Transylvanian food culture'}
For each day provide:
- Platform (Instagram/Facebook/TikTok)
- Content type (photo/video/story)
- Caption
- Best posting time
- Engagement strategy`,

  campaign: `Create a 2-week social media campaign:
Goal: ${input.goal || 'Launch new menu item'}
Budget: ${input.budget || 'Low-cost organic reach'}
Include:
- Campaign theme
- Content pillars
- Posting schedule
- Hashtag strategy
- Engagement tactics
- Success metrics`,

  engagement: `Create 10 responses to customer comments:
Scenario: ${input.scenario || 'positive review'}
Brand voice: Friendly, slightly mysterious, Transylvanian-themed
Include emojis and encourage return visits`
};

const selectedPrompt = prompts[input.content_type || 'instagram_post'];

return [{
  json: {
    prompt: selectedPrompt,
    content_type: input.content_type,
    context: input
  }
}];

const aiResponse = $input.item.json;
const context = $node['Build Social Prompt'].json.context;

return [{
  json: {
    platform: context.content_type,
    content: aiResponse.results[0].response,
    created_at: new Date().toISOString(),
    mitch_tips: [
      "Always include vampire/Transylvanian emoji: 🧛‍♂️🏰🦇",
      "Post during lunch (12-2pm) and dinner (6-8pm) hours",
      "Use location tags: Bucharest, Romania",
      "Engage with food bloggers and influencers"
    ]
  }
}];
